// Example of configuring clock skew in a JWT validator
JWTClaimsSet claims = JWTParser.parse(token).getJWTClaimsSet();
DefaultJWTClaimsVerifier verifier = new DefaultJWTClaimsVerifier(
    new JWTClaimsSet.Builder().build(),
    new HashSet<>(Arrays.asList("sub", "iat", "exp"))
);
// Allowing 60 seconds of drift to handle minor server desync
verifier.setMaxClockSkew(60);
verifier.verify(claims, null);
